import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { buildParserFile } from '@lezer/generator';

/** Every Lezer grammar this package owns, by directory and file stem. */
export const grammarNames = ['bash', 'csharp', 'jsonc', 'kcl', 'openscad', 'stepfile', 'stl', 'sysml', 'usd'] as const;

const generatedHeader =
  '/* oxlint-disable -- generated by `pnpm --filter @taucad/grammars generate` from the adjacent .grammar file */\n' +
  '/* eslint-disable -- generated parser tables */\n';

/** The parser and term modules a grammar compiles to, exactly as they are committed. */
export function generateParser(name: string, sourceDirectory: string): Readonly<{ parser: string; terms: string }> {
  const fileName = `${name}.grammar`;
  const source = readFileSync(join(sourceDirectory, name, fileName), 'utf8');
  const { parser, terms } = buildParserFile(source, {
    fileName,
    typeScript: true,
    moduleStyle: 'es',
    warn(message) {
      throw new Error(`${fileName}: ${message}`);
    },
  });
  return { parser: generatedHeader + parser, terms: generatedHeader + terms };
}

const sourceDirectory = import.meta.dirname;

if (process.argv[1] === import.meta.filename) {
  for (const name of grammarNames) {
    const { parser, terms } = generateParser(name, sourceDirectory);
    writeFileSync(join(sourceDirectory, name, `${name}.parser.ts`), parser);
    writeFileSync(join(sourceDirectory, name, `${name}.parser.terms.ts`), terms);
  }
}
